import { expect, expectStatus, test, type Document, type Extraction, type Vendor } from "../../fixtures";

test.describe("vendor lifecycle: replacement resubmission", () => {
  test(
    "after a replacement, only the new document waits for review",
    { tag: "@LIF-05" },
    async ({ apiAs, factory }) => {
      // Arrange: a vendor in review; a reviewer approves insurance and contract, rejects the w9.
      const { vendor, documents, extractions } = await factory.vendorInReview({ as: "member" });
      const reviewer = await apiAs("reviewer");
      const decide = (extraction: Extraction, body: object) =>
        reviewer.post(`/api/extractions/${extraction.id}/decision`, { data: body });
      await expectStatus(
        await decide(extractions.insurance_certificate, { decision: "approve" }),
        200,
      );
      await expectStatus(await decide(extractions.contract, { decision: "approve" }), 200);
      await expectStatus(
        await decide(extractions.w9, { decision: "reject", note: "Legal name does not match" }),
        200,
      );

      // Act: the member replaces the w9, waits for extraction, and resubmits the vendor.
      const member = await apiAs("member");
      const replacement: Document = await factory.upload(vendor.id, "w9");
      await expect
        .poll(
          async () =>
            (await expectStatus<Document>(await member.get(`/api/documents/${replacement.id}`), 200))
              .status,
          { message: "replacement w9 finishes extraction", timeout: 30_000 },
        )
        .toBe("extracted");
      await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

      // Assert: the stored vendor is back in review.
      const stored = await expectStatus<Vendor>(await member.get(`/api/vendors/${vendor.id}`), 200);
      expect(stored.status).toBe("in_review");

      // Assert: the review queue lists the vendor with exactly one pending extraction, the w9.
      const queue = await expectStatus<
        { vendor_id: string; extractions: { kind: string; status: string }[] }[]
      >(await reviewer.get("/api/review-queue"), 200);
      const item = queue.find((i) => i.vendor_id === vendor.id);
      expect(item, "vendor appears in the review queue").toBeDefined();
      expect(item?.extractions.map((e) => e.kind)).toEqual(["w9"]);
      expect(item?.extractions[0]?.status).toBe("pending_review");
    },
  );
});
